	for k, v := range m.MInt32Int64 {
		_, _ = k, v
		l := 1 + (bits.Len64((uint64(int64(k)))|1)+6)/7 + 1 + (bits.Len64((uint64(v))|1)+6)/7
		n += 1 + l + (bits.Len64((uint64(l))|1)+6)/7
	}
	for k, v := range m.MBoolBytes {
		_, _ = k, v
		l := 1 + 1 + 1 + len(v) + (bits.Len64((uint64(len(v)))|1)+6)/7
		n += 1 + l + (bits.Len64((uint64(l))|1)+6)/7
	}
