		_, _ = k, v
		lv := v.ProtoSize()
		l := 1 + (bits.Len64((uint64((k)<<1)^uint64((k)>>63))|1)+6)/7 + 1 + lv + (bits.Len64((uint64(lv))|1)+6)/7
		n += 1 + l + (bits.Len64((uint64(l))|1)+6)/7
